        cycle = []
        x = start
        while not visited[x]:
            visited[x] = True
            cycle.append(x)
            x = p[x - 1]
        return cycle

    # Find all cycles
    for i in range(1, n + 1):
        if not visited[i]:
            cycle = dfs(i)
            cycles[len(cycle)].append(cycle)

    # Check if any cycle has an odd length
    for cycle_length in cycles:
        if cycle_length % 2 != 0:
            return [-1]

    # Construct the permutation q
    q = [0] * (n + 1)
